/* PCP (RFC 6887) / NAT-PMP (RFC 6886) codec (design §8, task B4).
 *
 * Self-contained TU: loads the committed golden vectors
 * (test/vectors/pcp/pcp.bin + .meta.json, generated by
 * test/scripts/pcp_vectors.py, which packs the RFC figures with struct and
 * shares no code with this file) and asserts
 *   - every builder reproduces its vector byte for byte,
 *   - every parser case returns exactly 0 / -1 / -2 / 1 and, on success, only
 *     the fields a well-formed matching response carries,
 *   - the CGNAT/private classifier on the 16-byte form.
 * Parser cases are copied into a 0xDB-poisoned buffer, so any byte read past n
 * is a value no legal packet holds. (ASan would be the stronger check; it is
 * not part of `make test`.) */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "golden_meta.h"
#include "../src/proto/ntx_pcp.c"
#include "../src/crypto/ntx_sha256.c"

static int fails;

static void check(int cond, const char *name) {
    if (cond) printf("PASS %s\n", name);
    else { printf("FAIL %s\n", name); fails = 1; }
}

static uint8_t *read_file(const char *path, size_t *n) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
    long sz = ftell(f);
    if (sz < 0) { fclose(f); return NULL; }
    if (fseek(f, 0, SEEK_SET) != 0) { fclose(f); return NULL; }
    uint8_t *buf = malloc(sz > 0 ? (size_t)sz : 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    fclose(f);
    if (rd != (size_t)sz) { free(buf); return NULL; }
    *n = (size_t)sz;
    return buf;
}

static int hexnib(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

/* Decode an even-length hex string. Returns byte count, or -1 on malformed. */
static long hexbytes(const char *hex, uint8_t *out, size_t cap) {
    size_t len = strlen(hex);
    if (len % 2 != 0 || len / 2 > cap) return -1;
    for (size_t i = 0; i < len / 2; i++) {
        int hi = hexnib(hex[2 * i]), lo = hexnib(hex[2 * i + 1]);
        if (hi < 0 || lo < 0) return -1;
        out[i] = (uint8_t)((hi << 4) | lo);
    }
    return (long)(len / 2);
}

static const gm *find_case(const gm *cases, const char *name) {
    for (size_t i = 0; i < cases->ne; i++) {
        const char *n = NULL;
        if (gm_str(gm_get(cases->el[i], "name"), &n) == 0 && strcmp(n, name) == 0)
            return cases->el[i];
    }
    return NULL;
}

/* Case payload copied into a 0xDB-poisoned buffer, offset by PAD, so every
 * byte beyond n is a value no legal packet holds. */
#define PAD 64
static uint8_t buf[2048];

static uint8_t *case_bytes(const gm *c, size_t *len) {
    const char *hex = NULL;
    int64_t ln = -1;
    if (gm_str(gm_get(c, "hex"), &hex) != 0 || gm_num(gm_get(c, "len"), &ln) != 0 ||
        ln < 0 || ln > (int64_t)(sizeof buf) - PAD) return NULL;
    *len = (size_t)ln;
    memset(buf, 0xDB, sizeof buf);
    return hexbytes(hex, buf + PAD, sizeof buf - PAD) == (long)*len ? buf + PAD : NULL;
}

static void tname(char *out, size_t cap, const char *pfx, const char *name) {
    snprintf(out, cap, "%s-%s", pfx, name);
}

static int str_field(const gm *c, const char *k, const char **out) {
    return gm_str(gm_get(c, k), out);
}
static int num_field(const gm *c, const char *k, int64_t *out) {
    return gm_num(gm_get(c, k), out);
}

/* ------------------------------------------------------------------ */
static void test_builders(const gm *cases) {
    static const char *names[] = {
        "map_req_tcp", "map_req_udp_zero_sugg", "map_req_delete",
        "natpmp_addr_req", "natpmp_map_req_udp", "natpmp_map_req_tcp"
    };
    char tn[160];
    for (size_t i = 0; i < sizeof names / sizeof names[0]; i++) {
        const gm *c = find_case(cases, names[i]);
        size_t len = 0;
        const char *kind = NULL;
        const uint8_t *want;
        int64_t expect = -1;
        uint8_t out[128];
        size_t got = 0;
        if (!c || !(want = case_bytes(c, &len)) ||
            str_field(c, "kind", &kind) != 0 ||
            num_field(c, "expect", &expect) != 0 || len != (size_t)expect) {
            check(0, names[i]);
            continue;
        }
        memset(out, 0x5A, sizeof out);
        if (strcmp(kind, "build_pcp_map") == 0) {
            uint8_t ip[16], nonce[12];
            const char *cs_ip = NULL, *cs_nonce = NULL;
            int64_t proto, ipt, sugg, lifetime;
            if (str_field(c, "client_ip", &cs_ip) != 0 ||
                str_field(c, "nonce", &cs_nonce) != 0 ||
                hexbytes(cs_ip, ip, 16) != 16 ||
                hexbytes(cs_nonce, nonce, 12) != 12 ||
                num_field(c, "proto", &proto) != 0 ||
                num_field(c, "int_port", &ipt) != 0 ||
                num_field(c, "sugg_port", &sugg) != 0 ||
                num_field(c, "lifetime", &lifetime) != 0) {
                check(0, names[i]);
                continue;
            }
            got = pcp_build_map(out, ip, nonce, (uint8_t)proto, (uint16_t)ipt,
                                (uint16_t)sugg, (uint32_t)lifetime);
        } else if (strcmp(kind, "build_natpmp_addr") == 0) {
            got = natpmp_build_addr(out);
        } else if (strcmp(kind, "build_natpmp_map") == 0) {
            int64_t op, ipt, sugg, lifetime;
            if (num_field(c, "op", &op) != 0 ||
                num_field(c, "int_port", &ipt) != 0 ||
                num_field(c, "sugg_port", &sugg) != 0 ||
                num_field(c, "lifetime", &lifetime) != 0) {
                check(0, names[i]);
                continue;
            }
            got = natpmp_build_map(out, (uint8_t)op, (uint16_t)ipt,
                                   (uint16_t)sugg, (uint32_t)lifetime);
        } else {
            check(0, names[i]);
            continue;
        }
        tname(tn, sizeof tn, "build", names[i]);
        check(got == (size_t)expect && memcmp(out, want, got) == 0, tn);

        /* The builder must not write past its own length. */
        int clean = 1;
        for (size_t k = got; k < sizeof out; k++) if (out[k] != 0x5A) clean = 0;
        tname(tn, sizeof tn, "build-tail", names[i]);
        check(clean, tn);
    }

    check(NTX_PCP_PORT == 5351, "const-port");
    check(NTX_PCP_PROTO_TCP == 6 && NTX_PCP_PROTO_UDP == 17, "const-proto");
}

/* ------------------------------------------------------------------ */
static void test_parse_pcp(const gm *cases) {
    char tn[160];
    for (size_t i = 0; i < cases->ne; i++) {
        const gm *c = cases->el[i];
        const char *kind = NULL, *name = NULL, *nonce_s = NULL;
        if (str_field(c, "kind", &kind) != 0 || strcmp(kind, "parse_pcp_map")) continue;
        if (str_field(c, "name", &name) != 0) continue;
        size_t len = 0;
        uint8_t *msg = case_bytes(c, &len);
        int64_t proto, int_port, expect, ext_port, lifetime, epoch, result;
        uint8_t nonce[12];
        ntx_pcp_map_resp r;
        if (!msg || str_field(c, "nonce", &nonce_s) != 0 ||
            hexbytes(nonce_s, nonce, 12) != 12 ||
            num_field(c, "proto", &proto) != 0 ||
            num_field(c, "int_port", &int_port) != 0 ||
            num_field(c, "expect", &expect) != 0 ||
            num_field(c, "ext_port", &ext_port) != 0 ||
            num_field(c, "lifetime", &lifetime) != 0 ||
            num_field(c, "epoch", &epoch) != 0 ||
            num_field(c, "result", &result) != 0) {
            check(0, "pcp-fields");
            continue;
        }
        memset(&r, 0xCC, sizeof r);
        int rc = pcp_parse_map(msg, len, nonce, (uint8_t)proto,
                              (uint16_t)int_port, &r);
        tname(tn, sizeof tn, "pcp", name);
        check(rc == (int)expect, tn);
        if (expect != 0) continue;
        const char *ext_ip_s = NULL;
        uint8_t ext_ip[16];
        tname(tn, sizeof tn, "pcp-fields", name);
        check(r.result == (uint8_t)result && r.lifetime == (uint32_t)lifetime &&
              r.epoch == (uint32_t)epoch && r.ext_port == (uint16_t)ext_port &&
              str_field(c, "ext_ip", &ext_ip_s) == 0 &&
              hexbytes(ext_ip_s, ext_ip, 16) == 16 &&
              memcmp(r.ext_ip16, ext_ip, 16) == 0, tn);
    }
}

static void test_parse_natpmp(const gm *cases) {
    char tn[160];
    for (size_t i = 0; i < cases->ne; i++) {
        const gm *c = cases->el[i];
        const char *kind = NULL, *name = NULL;
        if (str_field(c, "kind", &kind) != 0 || str_field(c, "name", &name) != 0)
            continue;
        size_t len = 0;
        uint8_t *msg = case_bytes(c, &len);
        int64_t expect;
        if (!msg || num_field(c, "expect", &expect) != 0) continue;
        if (strcmp(kind, "parse_natpmp_addr") == 0) {
            uint8_t ip[4], want[4];
            const char *ext_ip_s = NULL;
            memset(ip, 0xCC, sizeof ip);
            int rc = natpmp_parse_addr(msg, len, ip);
            tname(tn, sizeof tn, "natpmp-addr", name);
            check(rc == (int)expect, tn);
            if (expect == 0) {
                tname(tn, sizeof tn, "natpmp-addr-ip", name);
                check(str_field(c, "ext_ip", &ext_ip_s) == 0 &&
                      hexbytes(ext_ip_s, want, 4) == 4 &&
                      memcmp(ip, want, 4) == 0, tn);
            }
        } else if (strcmp(kind, "parse_natpmp_map") == 0) {
            int64_t op, int_port, ext_port, lifetime;
            uint16_t ep = 0xCC;
            uint32_t lt = 0xCCCCCCCCu;
            if (num_field(c, "op", &op) != 0 ||
                num_field(c, "int_port", &int_port) != 0 ||
                num_field(c, "ext_port", &ext_port) != 0 ||
                num_field(c, "lifetime", &lifetime) != 0) {
                check(0, "natpmp-map-fields");
                continue;
            }
            int rc = natpmp_parse_map(msg, len, (uint8_t)op, (uint16_t)int_port,
                                     &ep, &lt);
            tname(tn, sizeof tn, "natpmp-map", name);
            check(rc == (int)expect, tn);
            if (expect == 0) {
                tname(tn, sizeof tn, "natpmp-map-val", name);
                check(ep == (uint16_t)ext_port && lt == (uint32_t)lifetime, tn);
            }
        }
    }
}

static void test_cgnat(const gm *cases) {
    char tn[160];
    for (size_t i = 0; i < cases->ne; i++) {
        const gm *c = cases->el[i];
        const char *kind = NULL, *name = NULL;
        if (str_field(c, "kind", &kind) != 0 || strcmp(kind, "cgnat")) continue;
        if (str_field(c, "name", &name) != 0) continue;
        int64_t expect;
        uint8_t ip[16];
        size_t len = 0;
        if (!case_bytes(c, &len) || len != 16 ||
            num_field(c, "expect", &expect) != 0) {
            check(0, "cgnat-fields");
            continue;
        }
        memcpy(ip, buf + PAD, 16);
        tname(tn, sizeof tn, "cgnat", name);
        check(pcp_ip_is_cgnat_or_private(ip) == (int)expect, tn);
    }
}

/* The brief's three named classifier cases, spelled out without the vectors. */
static void test_cgnat_brief(void) {
    uint8_t a[16], b[16], c[16];
    check(hexbytes("00000000000000000000ffff64400001", a, 16) == 16 &&
          hexbytes("00000000000000000000ffff64800001", b, 16) == 16 &&
          hexbytes("00000000000000000000ffff08080808", c, 16) == 16, "brief-hex");
    check(pcp_ip_is_cgnat_or_private(a) == 1, "brief-100.64.0.1-is-cgnat");
    check(pcp_ip_is_cgnat_or_private(b) == 0, "brief-100.128.0.1-public");
    check(pcp_ip_is_cgnat_or_private(c) == 0, "brief-8.8.8.8-public");
}

int main(void) {
    size_t mn = 0;
    uint8_t *meta = read_file("test/vectors/pcp/pcp.meta.json", &mn);
    check(meta != NULL, "meta-read");
    if (!meta) return 1;

    gm root;
    check(gm_parse((const char *)meta, mn, &root) == 0, "meta-parse");
    if (root.t != GM_OBJ) { check(0, "meta-obj"); free(meta); return 1; }

    const gm *binp = gm_get(&root, "bin");
    const gm *shap = gm_get(&root, "bin_sha256");
    const gm *cnt = gm_get(&root, "count");
    const gm *cases = gm_get(&root, "cases");
    const char *binname = NULL, *want_sha = NULL;
    int64_t ecnt = -1;
    check(binp && shap && cnt && cases && cases->t == GM_ARR &&
          gm_str(binp, &binname) == 0 && binname &&
          gm_str(shap, &want_sha) == 0 && want_sha &&
          gm_num(cnt, &ecnt) == 0 && (int64_t)cases->ne == ecnt, "meta-shape");
    if (!cases || cases->t != GM_ARR) { free(meta); return 1; }

    uint8_t *blob = read_file(binname, &mn);
    check(blob != NULL, "bin-read");
    if (!blob) { gm_free(&root); free(meta); return 1; }
    uint8_t dig[32];
    char dighex[65];
    ntx_sha256(blob, mn, dig);
    for (int i = 0; i < 32; i++) sprintf(dighex + 2 * i, "%02x", dig[i]);
    dighex[64] = 0;
    check(strcmp(dighex, want_sha) == 0, "bin-sha256");

    test_builders(cases);
    test_parse_pcp(cases);
    test_parse_natpmp(cases);
    test_cgnat(cases);
    test_cgnat_brief();

    free(blob);
    gm_free(&root);
    free(meta);
    return fails ? 1 : 0;
}
